'use strict'

const { Transform } = require('stream')
const { StringDecoder } = require('string_decoder')

/**
 * Private symbol for the partial line buffered between chunks.
 */
const kLast = Symbol('last')

/**
 * Private symbol for the StringDecoder instance.
 */
const kDecoder = Symbol('decoder')

/**
 * Determine whether a value exposes a Symbol.split method on itself or
 * anywhere on its prototype chain. Uses Object.getOwnPropertyDescriptor to
 * avoid triggering getter side effects.
 *
 * @param {unknown} value
 * @returns {boolean}
 */
function hasSplitMethod (value) {
  if (typeof value !== 'object' || value === null) {
    return false
  }

  let proto = value
  while (proto !== null) {
    const descriptor = Object.getOwnPropertyDescriptor(proto, Symbol.split)
    if (descriptor !== undefined && typeof descriptor.value === 'function') {
      return true
    }
    proto = Object.getPrototypeOf(proto)
  }

  return false
}

/**
 * Determine whether a value should be treated as an options object.
 *
 * @param {unknown} value
 * @returns {boolean}
 */
function isOptionsObject (value) {
  return typeof value === 'object' &&
    value !== null &&
    !(value instanceof RegExp) &&
    !hasSplitMethod(value)
}

/**
 * Determine whether a value is a valid chunk delimiter.
 *
 * @param {unknown} value
 * @returns {boolean}
 */
function isValidMatcher (value) {
  return typeof value === 'string' ||
    value instanceof RegExp ||
    hasSplitMethod(value)
}

/**
 * Identity mapper that returns the input unchanged.
 *
 * @param {unknown} incoming
 * @returns {unknown}
 */
function noop (incoming) {
  return incoming
}

/**
 * Push a mapped value down the stream if it is not undefined.
 *
 * @param {Transform} self
 * @param {unknown} val
 * @returns {void}
 */
function push (self, val) {
  if (val !== undefined) {
    self.push(val)
  }
}

/**
 * Transform implementation that splits incoming text by the configured
 * delimiter, maps each resulting chunk, and handles line-length overflow.
 *
 * @this {Transform}
 * @param {Buffer|string} chunk
 * @param {string} enc
 * @param {Function} cb
 * @returns {void}
 */
function transform (chunk, enc, cb) {
  let list

  if (this.overflow) {
    // Buffer is over the configured maxLength. Discard everything until the
    // next delimiter is found.
    const buf = this[kDecoder].write(chunk)
    list = buf.split(this.matcher)

    if (list.length === 1) {
      // No delimiter in this chunk; keep discarding.
      return cb()
    }

    // Discard the trailing fragment of the overlong line and resume normal
    // processing from the next complete line.
    list.shift()
    this.overflow = false
  } else {
    this[kLast] += this[kDecoder].write(chunk)
    list = this[kLast].split(this.matcher)
  }

  this[kLast] = list.pop()

  for (const line of list) {
    try {
      push(this, this.mapper(line))
    } catch (error) {
      return cb(error)
    }
  }

  this.overflow = this[kLast].length > this.maxLength
  if (this.overflow && !this.skipOverflow) {
    return cb(new Error('maximum buffer reached'))
  }

  cb()
}

/**
 * Flush implementation that forwards any remaining buffered text.
 *
 * @this {Transform}
 * @param {Function} cb
 * @returns {void}
 */
function flush (cb) {
  this[kLast] += this[kDecoder].end()

  if (this[kLast]) {
    try {
      push(this, this.mapper(this[kLast]))
    } catch (error) {
      return cb(error)
    }
  }

  cb()
}

/**
 * Normalize and validate the maxLength option.
 *
 * @param {unknown} maxLength
 * @returns {number|undefined}
 */
function normalizeMaxLength (maxLength) {
  if (maxLength === undefined || maxLength === null) {
    return undefined
  }

  if (typeof maxLength !== 'number' || !Number.isFinite(maxLength) || maxLength < 0) {
    throw new TypeError('maxLength must be a non-negative finite number')
  }

  return maxLength
}

/**
 * Create a Transform stream that splits incoming data by a delimiter.
 *
 * Supports the following calling conventions:
 *   - split(mapper)
 *   - split(options)
 *   - split(matcher, mapper)
 *   - split(matcher, options)
 *   - split(matcher, mapper, options)
 *
 * @param {RegExp|string|Function|Object} [matcher]
 * @param {Function|Object} [mapper]
 * @param {Object} [options]
 * @returns {Transform}
 */
function split (matcher, mapper, options) {
  // Apply defaults while preserving legacy falsy-input behaviour.
  matcher = matcher || /\r?\n/
  mapper = mapper || noop
  options = options || {}

  // Resolve the overloaded first argument.
  if (arguments.length === 1) {
    if (typeof matcher === 'function') {
      mapper = matcher
      matcher = /\r?\n/
    } else if (isOptionsObject(matcher)) {
      options = matcher
      matcher = /\r?\n/
    }
  } else if (arguments.length === 2) {
    if (typeof matcher === 'function') {
      options = mapper
      mapper = matcher
      matcher = /\r?\n/
    } else if (isOptionsObject(mapper)) {
      options = mapper
      mapper = noop
    }
  }

  if (typeof mapper !== 'function') {
    throw new TypeError('mapper must be a function')
  }

  if (!isValidMatcher(matcher)) {
    throw new TypeError('matcher must be a string, RegExp, or implement Symbol.split')
  }

  // Use a null-prototype target to avoid prototype pollution from user
  // options while preserving all own enumerable stream options.
  options = Object.assign(Object.create(null), options)
  options.autoDestroy = true
  options.transform = transform
  options.flush = flush
  options.readableObjectMode = true

  const stream = new Transform(options)

  stream[kLast] = ''
  stream[kDecoder] = new StringDecoder('utf8')
  stream.matcher = matcher
  stream.mapper = mapper
  stream.maxLength = normalizeMaxLength(options.maxLength)
  stream.skipOverflow = options.skipOverflow || false
  stream.overflow = false

  stream._destroy = function (err, cb) {
    // Work around a Node.js v12 bug where the writable state's error flag is
    // not reset, which can suppress subsequent error reporting.
    this._writableState.errorEmitted = false
    cb(err)
  }

  return stream
}

module.exports = split